/// Plural form selection, copied from the Plural-Forms header of each
/// upstream catalog.
#[rustfmt::skip]
#[allow(unused_comparisons)] // the rules are copied verbatim from upstream
#[allow(
    clippy::modulo_one,
    clippy::absurd_extreme_comparisons,
    clippy::nonminimal_bool,
    clippy::overly_complex_bool_expr,
    clippy::if_same_then_else,
    clippy::manual_range_contains
)]
fn plural_index(locale: &str, n: u64) -> usize {
    match locale {
        "af" => if n != 1 { 1 } else { 0 },
        "ar" => if n == 0 { 0 } else { if n == 1 { 1 } else { if n == 2 { 2 } else { if ((n % 100) >= 3) && ((n % 100) <= 10) { 3 } else { if (n % 100) >= 11 { 4 } else { 5 } } } } },
        "bg" => if n != 1 { 1 } else { 0 },
        "bn" => if n > 1 { 1 } else { 0 },
        "bo" => 0,
        "ca" => if n != 1 { 1 } else { 0 },
        "cs" => if (n == 1) && ((n % 1) == 0) { 0 } else { if ((n >= 2) && (n <= 4)) && ((n % 1) == 0) { 1 } else { if (n % 1) != 0 { 2 } else { 3 } } },
        "cy" => if n == 1 { 0 } else { if n == 2 { 1 } else { if (n != 8) && (n != 11) { 2 } else { 3 } } },
        "da" => if n != 1 { 1 } else { 0 },
        "de" => if n != 1 { 1 } else { 0 },
        "el_GR" => if n != 1 { 1 } else { 0 },
        "en" => if n != 1 { 1 } else { 0 },
        "eo" => if n != 1 { 1 } else { 0 },
        "es" => if n != 1 { 1 } else { 0 },
        "et" => if n != 1 { 1 } else { 0 },
        "eu" => if n != 1 { 1 } else { 0 },
        "fa_IR" => if n > 1 { 1 } else { 0 },
        "fi" => if n != 1 { 1 } else { 0 },
        "fil" => if (((n == 1) || (n == 2)) || (n == 3)) || ((((n % 10) != 4) || ((n % 10) != 6)) || ((n % 10) != 9)) { 1 } else { 0 },
        "fr" => if n > 1 { 1 } else { 0 },
        "ga" => if n == 1 { 0 } else { if n == 2 { 1 } else { if (n > 2) && (n < 7) { 2 } else { if (n > 6) && (n < 11) { 3 } else { 4 } } } },
        "gl" => if n != 1 { 1 } else { 0 },
        "he" => if n == 1 { 0 } else { if n == 2 { 1 } else { if (n > 10) && ((n % 10) == 0) { 2 } else { 3 } } },
        "hr" => if ((n % 10) == 1) && ((n % 100) != 11) { 0 } else { if (((n % 10) >= 2) && ((n % 10) <= 4)) && (((n % 100) < 10) || ((n % 100) >= 20)) { 1 } else { 2 } },
        "hu" => if n != 1 { 1 } else { 0 },
        "ia" => if n != 1 { 1 } else { 0 },
        "id" => 0,
        "it" => if n != 1 { 1 } else { 0 },
        "ja" => 0,
        "ko" => 0,
        "lt" => if ((n % 10) == 1) && (((n % 100) > 19) || ((n % 100) < 11)) { 0 } else { if (((n % 10) >= 2) && ((n % 10) <= 9)) && (((n % 100) > 19) || ((n % 100) < 11)) { 1 } else { if (n % 1) != 0 { 2 } else { 3 } } },
        "lv" => if ((n % 10) == 0) || (((n % 100) >= 11) && ((n % 100) <= 19)) { 0 } else { if ((n % 10) == 1) && ((n % 100) != 11) { 1 } else { 2 } },
        "ms" => 0,
        "nb_NO" => if n != 1 { 1 } else { 0 },
        "nl" => if n != 1 { 1 } else { 0 },
        "oc" => if n != 1 { 1 } else { 0 },
        "pap" => if n == 1 { 0 } else { 1 },
        "pl" => if n == 1 { 0 } else { if (((n % 10) >= 2) && ((n % 10) <= 4)) && (((n % 100) < 12) || ((n % 100) > 14)) { 1 } else { if (((n != 1) && (((n % 10) >= 0) && ((n % 10) <= 1))) || (((n % 10) >= 5) && ((n % 10) <= 9))) || (((n % 100) >= 12) && ((n % 100) <= 14)) { 2 } else { 3 } } },
        "pt" => if n != 1 { 1 } else { 0 },
        "pt_BR" => if n > 1 { 1 } else { 0 },
        "ro" => if n == 1 { 0 } else { if (n == 0) || (((n % 100) > 0) && ((n % 100) < 20)) { 1 } else { 2 } },
        "ru" => if ((n % 10) == 1) && ((n % 100) != 11) { 0 } else { if (((n % 10) >= 2) && ((n % 10) <= 4)) && (((n % 100) < 12) || ((n % 100) > 14)) { 1 } else { if (((n % 10) == 0) || (((n % 10) >= 5) && ((n % 10) <= 9))) || (((n % 100) >= 11) && ((n % 100) <= 14)) { 2 } else { 3 } } },
        "si" => if n > 1 { 1 } else { 0 },
        "sk" => if ((n % 1) == 0) && (n == 1) { 0 } else { if (((n % 1) == 0) && (n >= 2)) && (n <= 4) { 1 } else { if (n % 1) != 0 { 2 } else { 3 } } },
        "sl" => if (n % 100) == 1 { 0 } else { if (n % 100) == 2 { 1 } else { if ((n % 100) == 3) || ((n % 100) == 4) { 2 } else { 3 } } },
        "sr" => if ((n % 10) == 1) && ((n % 100) != 11) { 0 } else { if (((n % 10) >= 2) && ((n % 10) <= 4)) && (((n % 100) < 10) || ((n % 100) >= 20)) { 1 } else { 2 } },
        "sv" => if n != 1 { 1 } else { 0 },
        "szl" => if n != 1 { 1 } else { 0 },
        "ta" => if n != 1 { 1 } else { 0 },
        "te" => if n != 1 { 1 } else { 0 },
        "th" => 0,
        "tr" => if n > 1 { 1 } else { 0 },
        "tt" => if n != 1 { 1 } else { 0 },
        "uk" => if (((n % 1) == 0) && ((n % 10) == 1)) && ((n % 100) != 11) { 0 } else { if ((((n % 1) == 0) && ((n % 10) >= 2)) && ((n % 10) <= 4)) && (((n % 100) < 12) || ((n % 100) > 14)) { 1 } else { if ((n % 1) == 0) && ((((n % 10) == 0) || (((n % 10) >= 5) && ((n % 10) <= 9))) || (((n % 100) >= 11) && ((n % 100) <= 14))) { 2 } else { 3 } } },
        "vi" => 0,
        "zh_Hans_CN" => 0,
        "zh_Hant_TW" => 0,
        _ => if n == 1 { 0 } else { 1 },
    }
}

/// The (singular, plural) pairs the UI uses with ngettext.
pub static NGETTEXT_PAIRS: &[(&str, &str)] = &[("Engine", "Engines"), ("Time", "Times")];

/// Plural form translations.  The upstream catalogs contain no msgid_plural
/// entries, so this table stays empty and ngettext falls back to the English
/// plural for every form except the singular (which uses the catalog entry).
fn plural_forms(_locale: &str, _msgid: &str) -> Option<&'static [&'static str]> {
    None
}

/// The catalog of a locale, or 'en' for an unknown one.
pub fn for_locale(locale: &str) -> Translator {
    Translator {
        locale: match_locale(locale),
    }
}

/// Resolve a (possibly regional) locale tag onto a shipped locale.
fn match_locale(locale: &str) -> &'static str {
    let normalized = locale.trim().replace('-', "_");
    if normalized.is_empty() {
        return "en";
    }
    for candidate in SHIPPED_LOCALES {
        if candidate.eq_ignore_ascii_case(&normalized) {
            return candidate;
        }
    }
    let language = normalized.split('_').next().unwrap_or("");
    if language.eq_ignore_ascii_case("zh") {
        let lower = normalized.to_ascii_lowercase();
        if lower.starts_with("zh_hant")
            || lower.starts_with("zh_tw")
            || lower.starts_with("zh_hk")
            || lower.starts_with("zh_mo")
        {
            return "zh_Hant_TW";
        }
        return "zh_Hans_CN";
    }
    for candidate in SHIPPED_LOCALES {
        if candidate.eq_ignore_ascii_case(language) {
            return candidate;
        }
    }
    "en"
}

/// The locales the port ships translations for.
pub fn available_locales() -> &'static [&'static str] {
    SHIPPED_LOCALES
}

impl Translator {
    /// The resolved locale of this translator.
    pub fn locale(&self) -> &'static str {
        self.locale
    }

    fn catalog(&self) -> Option<&'static Catalog> {
        CATALOGS
            .iter()
            .find(|catalog| catalog.locale == self.locale)
    }

    /// The translation of msgid, or msgid itself when the catalog has none.
    pub fn gettext<'a>(&'a self, msgid: &'a str) -> &'a str {
        match self.catalog() {
            Some(catalog) => catalog
                .messages
                .iter()
                .find(|(key, _)| *key == msgid)
                .map(|(_, value)| *value)
                .unwrap_or(msgid),
            None => msgid,
        }
    }

    /// The singular or plural translation of singular / plural for n.
    pub fn ngettext<'a>(&'a self, singular: &'a str, plural: &'a str, n: u64) -> &'a str {
        let index = plural_index(self.locale, n);
        if index == 0 {
            return self.gettext(singular);
        }
        if let Some(forms) = plural_forms(self.locale, singular) {
            if let Some(form) = forms.get(index) {
                if !form.is_empty() {
                    return form;
                }
            }
        }
        plural
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn english_is_the_fallback_for_unknown_locales() {
        let translator = for_locale("xx");
        assert_eq!(translator.locale(), "en");
        assert_eq!(translator.gettext("Preferences"), "Preferences");
    }

    #[test]
    fn regional_tags_resolve_onto_a_shipped_locale() {
        assert_eq!(for_locale("de-DE").locale(), "de");
        assert_eq!(for_locale("pt-BR").locale(), "pt_BR");
        assert_eq!(for_locale("zh-CN").locale(), "zh_Hans_CN");
        assert_eq!(for_locale("zh-TW").locale(), "zh_Hant_TW");
        assert_eq!(for_locale("zh-Hant").locale(), "zh_Hant_TW");
        assert_eq!(for_locale("ja_JP").locale(), "ja");
    }

    #[test]
    fn available_locales_contain_the_source_locale() {
        let locales = available_locales();
        assert!(locales.contains(&"en"));
        assert!(locales.contains(&"ja"));
        assert!(locales.contains(&"de"));
        assert!(locales.contains(&"zh_Hans_CN"));
    }

    #[test]
    fn every_shipped_locale_resolves_to_itself() {
        for locale in available_locales() {
            assert_eq!(for_locale(locale).locale(), *locale);
        }
    }

    #[test]
    fn every_catalog_uses_the_english_key_set() {
        let reference: Vec<&str> = MESSAGES_EN.iter().map(|(key, _)| *key).collect();
        for catalog in CATALOGS {
            let keys: Vec<&str> = catalog.messages.iter().map(|(key, _)| *key).collect();
            assert_eq!(
                keys, reference,
                "catalog {} does not use the reference msgids",
                catalog.locale
            );
        }
    }

    #[test]
    fn ngettext_uses_the_english_plural_for_the_plural_form() {
        let translator = for_locale("en");
        assert_eq!(translator.ngettext("Engine", "Engines", 1), "Engine");
        assert_eq!(translator.ngettext("Engine", "Engines", 2), "Engines");
    }

    #[test]
    fn ngettext_follows_the_locale_plural_rule() {
        // Japanese has nplurals=1: every count uses the singular form.
        let japanese = for_locale("ja");
        let singular = japanese.gettext("Engine");
        assert_eq!(japanese.ngettext("Engine", "Engines", 1), singular);
        assert_eq!(japanese.ngettext("Engine", "Engines", 5), singular);
        // French uses the plural for n > 1 (nplurals=2).
        let french = for_locale("fr");
        assert_eq!(
            french.ngettext("Engine", "Engines", 1),
            french.gettext("Engine")
        );
        assert_eq!(french.ngettext("Engine", "Engines", 2), "Engines");
    }

    #[test]
    fn plural_rules_follow_the_upstream_headers() {
        assert_eq!(plural_index("ar", 0), 0);
        assert_eq!(plural_index("ar", 2), 2);
        assert_eq!(plural_index("ar", 11), 4);
        assert_eq!(plural_index("pl", 2), 1);
        assert_eq!(plural_index("pl", 5), 2);
        assert_eq!(plural_index("ro", 0), 1);
        assert_eq!(plural_index("ro", 20), 2);
        assert_eq!(plural_index("ga", 7), 3);
    }

    #[test]
    fn every_ngettext_pair_is_translatable() {
        let translator = for_locale("ja");
        for (singular, plural) in NGETTEXT_PAIRS {
            let one = translator.ngettext(singular, plural, 1);
            let many = translator.ngettext(singular, plural, 7);
            assert!(!one.is_empty() && !many.is_empty());
            // nplurals=1: both forms come from the catalog entry.
            assert_eq!(one, many);
        }
    }

    #[test]
    fn translations_come_from_the_upstream_catalogs() {
        assert_eq!(for_locale("de").gettext("Preferences"), "Einstellungen");
        assert_eq!(for_locale("de").gettext("About"), "Über");
        assert_ne!(for_locale("ja").gettext("Preferences"), "Preferences");
        // An unknown msgid is returned unchanged.
        assert_eq!(for_locale("de").gettext("no such msgid"), "no such msgid");
    }
}
